"""Writes the prompt files of the multi-chat round: eight directions, dark and light.
Usage: python3 prompts.py   (writes <slug>-<theme>.txt beside itself)"""
from pathlib import Path
R = Path(__file__).parent

HEAD = """UI design mockup of the project screen of an AI software factory console, in its existing "Mission control" design: a near-black blue room (dark) or a warm cream day version (light), thin-bordered instrument panels with small corner marks, cyan as the system colour, amber as the one signal that needs a person, monospace figures, everything exact and calm. Desktop browser viewport, 16:9, flat, no browser chrome, no device frame, the screen fills the whole image.

The shell is fixed and must look like this: a quiet top bar ("Factory console", the project "ai-software-factory-code", links "Board", "New task", "Projects", "Resources", "Costs", "Policy", "Alerts", a theme toggle, "sebastian", "Log out"); under it the pulse band, one panel with the sentence "Two cards need your decision; #612's merge carries a migration." with an amber warning sign and a 3 px amber left rule, and under the sentence the instrument strip "● waiting on you | 3 working | 2 need you | €61.40 / €120.00 ▬▬▬▭▭ 51 % | GitHub: 1 open pull request"; then the main area: the chat on the left taking 40 percent of the width as the main region, and the board on the right taking 60 percent with its header row "Board", a small mono text box "Find: a word, #612, plan:558", "Wide view" and "?", and four columns: "Needs you 2" lit amber (a merge approval "Merge PR #612" with chips "high risk" "migration" and buttons "Approve", "Deny", "Split"; a question "#603 Which store for the session table?" with buttons "Postgres", "SQLite", "Ask the author"), "Queued 4", "In progress 5", "Done 8", each column head with a small ▾ at its right, the cards compact with a mono state row. No ticker at the foot."""

CONTENT = """What is new, and what this image is about: the chat holds many conversations, called threads. The content, spelled exactly. The open thread is titled "Session store: Postgres" and shows: you: "Why is #603 waiting?"; agent: "#603 asked which store the session table should use. The plan named Postgres; the brief allows SQLite for a single replica. I can answer Postgres for you."; a collapsed tool block "read card #603 · 0.4 s"; a proposal "I will: answer #603 with Postgres" with buttons "Do it" and "Skip". The threads, by last turn: "Inbox" (the factory's own thread, marked with an unread badge "2" and the newest line "Merge PR #612 waits for you: high risk, one migration"), "Plan: the members page" (a turn in flight, a small working mark, "14:26"), "Session store: Postgres" (open, "14:21"), "Costs read: the date window" ("yesterday"); and one archived thread "Export in pull request mode" shown last and dimmer. A "New" action for a new thread. The autonomy level of the project reads "assisted" and offers "manual", "assisted", "autonomous", "full auto". The composer at the chat's bottom: a prompt mark "›", the box "Ask or tell the project… (Enter sends, Shift+Enter breaks the line)", "Send", and a hint of the commands "/compact" and "/new". The browser tab's title would read "(2) Factory console"."""

TAIL = """Legible UI text with exact spelling, nothing invented, no lorem ipsum. The pulse stays the loudest thing on the screen after the amber Needs you column; the chat stays the main region; the thread list and the level selector are quiet instruments, the unread badge and the working mark are the only loud marks on them. Made by a top product design studio. Not a template, not a generic admin dashboard."""

D = [
 ("01-rail", "Rail", """The threads as a narrow rail inside the chat panel's left edge, 180 px wide, one row per thread: the title cut to one line, the time in mono at the right, the unread badge as a small amber pill with the count, the working mark as a breathing cyan dot before the title; "Inbox" is the first row with a small factory mark instead of a dot; archived rows sit under a hairline at the bottom in the faint colour; "New" as a small button at the rail's top. The level selector as a segmented control of four small mono buttons in the chat's head, right of "project agent", with "assisted" lit cyan. The open thread's log and the composer take the rest of the chat panel."""),
 ("02-tabs", "Tabs", """The threads as tabs across the chat panel's head, like a browser: "Inbox" as the pinned first tab with an amber badge "2", then "Plan: the members page" with a breathing dot, "Session store: Postgres" as the selected tab with a cyan underline, "Costs read: the date window", a "+" tab for New, and a "⋯" tab that opens the archived threads. The level selector in the top bar beside the project name, as a small mono select "assisted ▾". The log and the composer fill the panel under the tabs."""),
 ("03-title-menu", "Title menu", """One thread title in the chat's head, "Session store: Postgres ▾", that opens a list of the threads as a dropdown panel shown open in the image: "Inbox 2" with the amber badge, "Plan: the members page" with the working dot, "Session store: Postgres" checked, "Costs read: the date window", a hairline, "Export in pull request mode" dimmed with "restore", and at the foot "New thread", "Archive this thread", "Delete this thread…". The level selector as a row of four mono words under the instrument strip inside the pulse band, "manual · assisted · autonomous · full auto", with "assisted" lit and underlined in cyan. The badge "2" also sits on the title button."""),
 ("04-dock", "Dock", """The threads as a strip of chips directly above the composer, inside the chat panel, newest first: "Inbox 2" lit amber, "Plan: the members page ●" with the working dot, "Session store: Postgres" filled as the open one, "Costs read: the date window", "+ New"; archived threads behind a last chip "archived (1)". The log above the strip. The level selector inside the instrument strip as a fifth cell "autonomy: assisted ▾" between "need you" and the spend gauge. The composer under the strip with "/compact" and "/new" as two small mono chips at its right."""),
 ("05-command", "Command", """Keyboard first: the composer is the one control. Typing "/" shows a small palette above the box with "/new  a new thread", "/compact  compact this thread", "/archive", "/level assisted", shown open in the image with the first row selected; the thread switcher is a palette too, opened with ctrl+k, shown as a thin bar at the chat's head with the open thread's title "Session store: Postgres" and the counts "Inbox 2 · 1 working" beside it as mono text. The level selector as a line in the composer's foot: "assisted · changes confirm". Minimal chrome, mono everywhere in the chat's head and foot."""),
 ("06-instrument", "Instrument", """The level selector as a mission-control instrument in the status strip: a four-position selector drawn as four small square lamps in a row labelled "manual", "assisted", "autonomous", "full auto", the "assisted" lamp lit cyan with a glow, the others dark with hairline borders. The threads as a mono table at the chat's left, 200 px: columns for the mark, the title and the time, "Inbox" first with an amber "2" in the mark column, the working thread with "●" in cyan, the archived thread under a hairline with "arc" in the mark column. The chat's head reads "Session store: Postgres" with "New", "Archive" and "Delete…" as small text buttons."""),
 ("07-messenger", "Messenger", """A messenger's conversation list inside the chat panel's left third, each thread a two-line row: a round mark (the factory's mark for "Inbox", the initial of the thread's first word otherwise), the title bold when unread, the newest line in the faint colour ("Merge PR #612 waits for you: high risk, one migration" under Inbox), the time at the right, an amber count badge "2" on Inbox, a cyan breathing dot on "Plan: the members page"; "Archived (1)" as a folded row at the bottom; "New" as a round "+" button at the list's top right. The level selector in the chat's head as a pill "assisted" that opens the four levels. The open thread's log on the right two thirds of the chat panel with the composer at its foot."""),
 ("08-inbox-split", "Inbox split", """The inbox thread lives apart: the chat panel splits into two stacked regions, the inbox on top at a third of the height, titled "Inbox" with the amber badge "2", showing the newest poke as an agent turn "Merge PR #612 waits for you: high risk, one migration." with buttons "Approve", "Deny", "Open the card" beside a small reply box; the planning threads below as the main region with a thin tab row "Plan: the members page ● | Session store: Postgres | Costs read: the date window | +" and the open thread's log and composer. The level selector as four mono words in the top bar's centre, "manual assisted autonomous full auto", with "assisted" lit cyan."""),
]
for slug, name, body in D:
    for theme in ("dark", "light"):
        t = "Dark theme." if theme == "dark" else "Light theme: the cream day version of the same design, dark navy text on warm off-white panels, the same cyan and amber."
        (R / f"{slug}-{theme}.txt").write_text(f"{HEAD}\n\n{CONTENT}\n\nDirection \"{name}\": {body} {t}\n\n{TAIL}\n")
print(len(D) * 2, "prompts")
